<?php require_once 'includes/bootstrap.php'; require_login(); $pdo=db(); $u=current_user(); $s=$pdo->prepare('SELECT c.*,e.enrolled_at FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.enrolled_at DESC');$s->execute([$u['id']]);$courses=$s->fetchAll(); page_head('Dashboard','Your learner dashboard for enrolled courses and account information.');site_header('');render_flash(); ?>
<main><section class="page-hero"><div class="page-hero-content"><p class="section-label">MY LEARNING</p><h1>Welcome, <?= e($u['name']) ?></h1><p>Account role: <strong><?= e(ucfirst($u['role'])) ?></strong>. Manage your learning from this dashboard.</p></div></section><section><div class="dashboard-grid"><div class="card"><h2>My courses</h2><?php if($courses): ?><div class="dashboard-list"><?php foreach($courses as $c): ?><div class="dashboard-item"><img src="<?= e(url('images/'.$c['image'])) ?>" alt=""><div><h3><?= e($c['title']) ?></h3><p>Enrolled <?= e(date('d M Y',strtotime($c['enrolled_at']))) ?></p></div><a class="button secondary-button small" href="<?= e(url('course.php?id='.$c['id'])) ?>">Open</a></div><?php endforeach; ?></div><?php else: ?><p>You have not enrolled in a course yet.</p><a class="button primary-button" href="<?= e(url('courses.php')) ?>">Browse courses</a><?php endif; ?></div><aside class="card"><h2>Account</h2><p><strong>Name:</strong> <?= e($u['name']) ?></p><p><strong>Email:</strong> <?= e($u['email']) ?></p><p><strong>Role:</strong> <?= e(ucfirst($u['role'])) ?></p><?php if($u['role']==='admin'): ?><a class="button primary-button" href="<?= e(url('admin/index.php')) ?>">Open admin area</a><?php endif; ?></aside></div></section></main><?php site_footer(); ?>